7  \( Q(s, a) \leftarrow Q(s, a) + \alpha (r + \gamma Q(s', a') - Q(s, a)) \) ; // 更新 Q 函数

8  \( \pi(s) = \arg\max_{a \in |\mathcal{A}|} Q(s, a) \) ; // 更新策略

9  \( s \leftarrow s', a \leftarrow a' \) ;

10 until s 为终止状态;

11 until  \( \forall s, a, Q(s, a) \)  收敛;

